.outer img{ width:100%; }
.toolbar{
    position:fixed;
    right:10px;
    top:100px;
}
.toolbarItem{ background-color:bisque; border-top:1px dashed #ccc; }
.toolbarItem>a{ text-decoration:none; display:inline-block;
    padding:5px 10px; color:#F8534D; }
.toolbarItem>a:hover{ text-decoration:underline; }

